INSERT INTO practice_templates (name, description, groups_json, blocks_json, built_in, created_by) VALUES
  ('Throws (winter): Lift 1, squat + clean', 'Off-season lower-body day. Winter runs its own cycle, separate from M0-M4. Block 1 (Off weeks 1-4): learn the lifts, 3 x 8 at RPE 6-7. Block 2 (Off 5-8): 5 x 5 at RPE 7-8. Block 3 (Off 9 to first practice): 5 x 3 at RPE 8; the last week is the strength check at reduced volume, so athletes start the season fresh.', '["throws"]', '[{"kind": "warmup", "title": "Winter warm-up", "minutes": 12, "groups": ["throws"], "details": "Bike or jog 5 min, then: lunge with reach 2 x 6 each, lateral lunge 2 x 6 each, inchworms 2 x 5, glute bridges 2 x 10, broad jumps 2 x 3, empty-bar complex (RDL, hang high pull, front squat, press) 2 x 5.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Clean technique", "minutes": 15, "groups": ["throws"], "details": "Block 1: hang clean pull + hang power clean 5 x 3, light, learning positions. Block 2: hang power clean 5 x 3 (RPE 7). Block 3: power clean 6 x 2 (RPE 8). Every rep fast; stop the set when the bar slows or the catch gets messy.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Back squat", "minutes": 20, "groups": ["throws"], "details": "Block 1: 3 x 8 (RPE 6-7). Block 2: 5 x 5 (RPE 7-8). Block 3: 5 x 3 (RPE 8). Write the load down every week; add 5-10 lb when every rep is clean. Between sets: Copenhagen plank 0:20 each side.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Hinge + single leg", "minutes": 15, "groups": ["throws"], "details": "BB RDL 3 x 8, DB Bulgarian split squat 3 x 8 each, lateral lunge 2 x 8 each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Core + mobility", "minutes": 10, "groups": ["throws"], "details": "Pallof press 3 x 10 each, dead bugs 3 x 10, 90/90 hip stretch 2 x 1:00 each, deep squat hold 2 x 1:00.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (winter): Lift 2, press + upper back', 'Off-season upper-body day. Winter runs its own cycle, separate from M0-M4. Block 1 (Off weeks 1-4): learn the lifts, 3 x 8 at RPE 6-7. Block 2 (Off 5-8): 5 x 5 at RPE 7-8. Block 3 (Off 9 to first practice): 5 x 3 at RPE 8; the last week is the strength check at reduced volume, so athletes start the season fresh.', '["throws"]', '[{"kind": "warmup", "title": "Winter warm-up (upper)", "minutes": 12, "groups": ["throws"], "details": "Bike or jog 5 min, then: band pull-aparts 2 x 15, scap push-ups 2 x 10, wall slides 2 x 10, med-ball chest pass 2 x 8, plyo push-ups 2 x 5.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Bench press + row", "minutes": 20, "groups": ["throws"], "details": "Bench press, same sets and RPE as the block''s squat (3 x 8, then 5 x 5, then 5 x 3). Superset each set with chest-supported row x 8-10.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Push press", "minutes": 10, "groups": ["throws"], "details": "Blocks 1-2: 3 x 5. Block 3: 4 x 3. Dip and drive: the legs move the bar, the arms finish it.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Upper accessories", "minutes": 15, "groups": ["throws"], "details": "Pull-ups 3 x 6-8 (band if needed), SA DB incline press 3 x 8 each, SA DB row 3 x 10 each, DB reverse fly 3 x 12.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Shoulder care + core", "minutes": 10, "groups": ["throws"], "details": "SA DB external rotation 2 x 12 each, Y-T-W raises 2 x 8, side plank 3 x 0:30 each, farmer''s carry 3 x 30y.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (winter): Lift 3, power + med ball', 'Off-season power day: jumps, rotational med-ball throws (the winter stand-in for the ring), and a heavy pull. Winter runs its own cycle, separate from M0-M4. Block 1 (Off weeks 1-4): learn the lifts, 3 x 8 at RPE 6-7. Block 2 (Off 5-8): 5 x 5 at RPE 7-8. Block 3 (Off 9 to first practice): 5 x 3 at RPE 8; the last week is the strength check at reduced volume, so athletes start the season fresh.', '["throws"]', '[{"kind": "warmup", "title": "Winter warm-up", "minutes": 12, "groups": ["throws"], "details": "Bike or jog 5 min, then: lunge with reach 2 x 6 each, lateral lunge 2 x 6 each, inchworms 2 x 5, glute bridges 2 x 10, broad jumps 2 x 3, empty-bar complex (RDL, hang high pull, front squat, press) 2 x 5.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Jumps", "minutes": 10, "groups": ["throws"], "details": "Low volume, full rest: box jumps 3 x 3, broad jumps 3 x 3, lateral bounds 3 x 3 each. Stop a set when height or distance drops.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Med-ball power", "minutes": 15, "groups": ["throws"], "details": "Side scoop throws into the wall 4 x 5 each side, step-behind side throws 3 x 4 each, overhead back toss 3 x 4, scoop forward toss 3 x 4 (boys 4-6 kg, girls 3-4 kg). Max intent on every throw.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Trap-bar deadlift", "minutes": 15, "groups": ["throws"], "details": "Block 1: 3 x 6 (RPE 7). Block 2: 4 x 4 (RPE 8). Block 3: 4 x 3, fast, at RPE 7.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Sled + carries", "minutes": 10, "groups": ["throws"], "details": "Heavy sled push 4 x 15y, suitcase carry 3 x 30y each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Core + mobility", "minutes": 10, "groups": ["throws"], "details": "Pallof press 3 x 10 each, dead bugs 3 x 10, 90/90 hip stretch 2 x 1:00 each, deep squat hold 2 x 1:00.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (winter): Indoor throwing', 'For throwers entered in indoor meets (January-February), once or twice a week after a lift. Low throw counts; the season''s technique cycle starts at M0.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up (short)", "minutes": 10, "groups": ["throws"], "details": "Jog 400m, A-skips 2 x 20y, lateral line hops 2 x 10 each, duck walks 2 x 10y, striders 2 x 40y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Shot drills", "minutes": 20, "groups": ["throws"], "details": "Stand throws x10, step-back glides or half-turns x6, then 6-8 full throws. One cue per athlete.", "workoutId": null, "attempts": null, "results": []}, {"kind": "measured", "title": "Best throws", "minutes": 10, "groups": ["throws"], "details": "Measure the best three when an indoor meet is within two weeks; otherwise just throw.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "cooldown", "title": "Shoulder care + core", "minutes": 10, "groups": ["throws"], "details": "SA DB external rotation 2 x 12 each, Y-T-W raises 2 x 8, side plank 3 x 0:30 each, farmer''s carry 3 x 30y.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (winter): Strength check', 'First off-season week and the last week before first practice. The marks set the starting loads for M1 and show what winter lifting added. Same tests every time.', '["throws"]', '[{"kind": "warmup", "title": "Winter warm-up", "minutes": 12, "groups": ["throws"], "details": "Bike or jog 5 min, then: lunge with reach 2 x 6 each, lateral lunge 2 x 6 each, inchworms 2 x 5, glute bridges 2 x 10, broad jumps 2 x 3, empty-bar complex (RDL, hang high pull, front squat, press) 2 x 5.", "workoutId": null, "attempts": null, "results": []}, {"kind": "measured", "title": "Back squat, best clean triple", "minutes": 15, "groups": ["throws"], "details": "Work up to a set of 3 at RPE 8-9 with full depth and no grinders. Record the load in lb.", "workoutId": null, "attempts": 1, "results": []}, {"kind": "measured", "title": "Bench press, best clean triple", "minutes": 15, "groups": ["throws"], "details": "Work up to a set of 3 at RPE 8-9 with a pause on the chest. Record the load in lb.", "workoutId": null, "attempts": 1, "results": []}, {"kind": "measured", "title": "Standing long jump", "minutes": 10, "groups": ["throws"], "details": "Best of 3. Record feet and inches.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "measured", "title": "Overhead back med-ball throw", "minutes": 10, "groups": ["throws"], "details": "Best of 3. Boys 4 kg, girls 3 kg. Measure from the toe line.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "cooldown", "title": "Core + mobility", "minutes": 10, "groups": ["throws"], "details": "Pallof press 3 x 10 each, dead bugs 3 x 10, 90/90 hip stretch 2 x 1:00 each, deep squat hold 2 x 1:00.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27');
